{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/lab",
  "data": [
    {
      "name": "value",
      "type": "string",
      "description": "Identifies the tab in value, onChange and onReselect.",
      "required": true
    },
    {
      "name": "label",
      "type": "string",
      "description": "The tab's name, shown under its icon. Keep it to one short word.",
      "required": true
    },
    {
      "name": "icon",
      "type": "ReactNode",
      "description": "The tab's icon, an Icon at size lg. It is drawn in the current text colour, and in the accent colour while selected.",
      "required": true
    },
    {
      "name": "selectedIcon",
      "type": "ReactNode",
      "description": "The icon while the tab is selected, typically its filled variant. Defaults to icon."
    },
    {
      "name": "badge",
      "type": "string | number",
      "description": "A badge over the icon's top-trailing corner: a count or a short string such as \"!\". It appears, changes and disappears without animating. Omit it or pass an empty string for none."
    },
    {
      "name": "badgeLabel",
      "type": "string",
      "description": "What assistive technology reads for the badge after the tab's label, such as \"3 unread\". Defaults to the badge itself."
    },
    {
      "name": "panelId",
      "type": "string",
      "description": "Id of the panel this tab controls, wired up as aria-controls. Put the same id on the section's panel element."
    },
    {
      "name": "aria-disabled",
      "type": "boolean | 'true' | 'false'",
      "description": "Disables the tab, as on Core's Tab: it stays focusable but dimmed and is never chosen. A tap, a click or a key on it, or a lift over it, selects nothing, and the arrow keys skip it. A finger that lands on it lifts no lens until it drags or reaches an enabled tab, which the lift then chooses. This differs from iOS on purpose. iOS ignores a touch that starts on a disabled tab, but TabBar follows the action-group rule: the tab you lift on acts."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
